import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    s = str(n)
    total = 0
    for i, ch in enumerate(s, start=1):
        total += int(ch) ** i
    if total == n:
        print("Disarium Number")
    else:
        print("Not a Disarium Number")

if __name__ == "__main__":
    main()
